fn find_max(nums: Vec<i32>) -> i32 {
    // Initialize the candidate maximum with the first element.
    // Since the problem guarantees a non-empty array, unwrap is safe here.
    let mut iter = nums.into_iter();
    let mut max_val = iter.next().unwrap();

    // Scan the rest of the elements.
    for x in iter {
        if x > max_val {
            max_val = x;
        }
    }

    // Return the maximum value found.
    max_val
}

